const page = "<!doctype html>\r\n<html lang=\"es\">\r\n<head>\r\n  <meta charset=\"utf-8\">\r\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\r\n  <meta name=\"theme-color\" content=\"#f8f5ef\">\r\n  <meta name=\"description\" content=\"Un espacio para Karina y Michael: sus invitados, confirmaciones y mensajes para el gran día.\">\r\n  <title>Nuestro día · Karina y Michael</title>\r\n  <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\r\n  <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\r\n  <link href=\"https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Playfair+Display:wght@400;500;600&display=swap\" rel=\"stylesheet\">\r\n  <style>:root{--cream:#f8f5ef;--paper:#fffefa;--ink:#42362f;--muted:#81746c;--line:#e8ddd1;--rose:#b77e70;--rose-dark:#915e51;--sage:#dce4d9}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--cream);color:var(--ink);font:15px/1.6 'DM Sans',sans-serif;-webkit-font-smoothing:antialiased}button,input,select{font:inherit}button{cursor:pointer}a{color:inherit;text-decoration:none}:focus-visible{outline:3px solid var(--rose);outline-offset:3px}[hidden]{display:none!important}.site-header{height:82px;max-width:1440px;margin:auto;padding:0 clamp(24px,5vw,75px);display:flex;align-items:center;justify-content:space-between;gap:28px}.brand{display:flex;align-items:center;gap:14px;white-space:nowrap}.brand-mark{font:500 26px 'Playfair Display',serif;letter-spacing:-.08em}.brand-mark span{color:var(--rose);font-style:italic;padding:0 3px}.brand-caption{font-size:10px;letter-spacing:.24em;font-weight:700;border-left:1px solid #cebeb0;padding-left:15px}.site-header nav{display:flex;gap:32px;color:#6d6158;font-size:12px;font-weight:600}.site-header nav a:hover,.text-link:hover{color:var(--rose-dark)}.sync{display:flex;align-items:center;gap:9px;color:#8b8077;font-size:11px;white-space:nowrap}.sync-dot{width:7px;height:7px;border-radius:50%;background:#9baa91;box-shadow:0 0 0 4px #e7eee2}.hero{max-width:1440px;min-height:580px;margin:auto;display:grid;grid-template-columns:48% 52%;background:#eee5dc}.hero-copy{padding:clamp(45px,7vw,105px) clamp(30px,6vw,95px) 55px clamp(35px,7vw,110px);display:flex;flex-direction:column;align-items:flex-start;justify-content:center;background:radial-gradient(circle at 10% 70%,#fbf7f0,#eee5dc 95%)}.eyebrow{font-size:10px;letter-spacing:.23em;font-weight:700;color:var(--rose-dark);margin:0 0 18px}.hero h1,h2{font-family:'Playfair Display',serif;font-weight:500}.hero h1{font-size:clamp(43px,4.6vw,70px);line-height:1.14;letter-spacing:-.035em;margin:0 0 22px;max-width:640px}.hero h1 em{color:#ad7568;font-weight:400}.hero-intro{font-size:14px;line-height:1.8;color:#73665e;max-width:440px;margin:0}.hero-actions{display:flex;align-items:center;gap:28px;flex-wrap:wrap;margin-top:34px}.button{border-radius:4px;padding:13px 21px;font-weight:700;font-size:12px;display:inline-flex;gap:21px;align-items:center}.button-primary{background:var(--rose-dark);color:white}.button-primary:hover{background:#74483e}.text-link{font-size:12px;font-weight:700;border-bottom:1px solid #b7a196;padding-bottom:3px}.text-link span{margin-left:9px}.hero-note{margin-top:auto;padding-top:55px;display:flex;align-items:center;gap:13px;font-size:10px;letter-spacing:.17em;font-weight:700;color:#98867a}.note-line{width:28px;height:1px;background:#b9a498}.note-heart{font-size:18px;color:var(--rose);font-weight:400}.hero-photo{position:relative;min-height:580px;overflow:hidden}.hero-photo img{width:100%;height:100%;position:absolute;inset:0;object-fit:cover;object-position:50% 45%}.photo-caption{position:absolute;right:30px;bottom:24px;color:white;text-shadow:0 1px 10px #4d342b;font:italic 18px 'Playfair Display',serif}.content{max-width:1310px;margin:0 auto;padding:0 clamp(24px,4.5vw,68px) 82px}.error{margin-top:25px;padding:14px 18px;background:#fff0e9;border:1px solid #e8c2b3;border-radius:9px;color:#8e5140;font-size:12px}.welcome{display:flex;justify-content:space-between;align-items:end;gap:25px;padding:67px 0 27px}.welcome .eyebrow,.section-heading .eyebrow,.planning .eyebrow{margin-bottom:9px}.welcome h2,.section-heading h2,.planning h2{font-size:clamp(29px,3vw,39px);line-height:1.23;margin:0 0 8px;letter-spacing:-.02em}.welcome p:last-child,.section-heading p:last-child,.planning p:last-child{color:var(--muted);font-size:13px;margin:0}.refresh{background:transparent;border:1px solid #cfbdb0;border-radius:4px;color:#76594d;font-size:11px;font-weight:700;padding:10px 13px;white-space:nowrap}.refresh:hover{background:#efe6dc}.refresh:disabled{opacity:.5;cursor:wait}.refresh span{font-size:17px;line-height:0;vertical-align:-1px;margin-left:7px}.overview{background:var(--paper);border:1px solid var(--line);display:grid;grid-template-columns:1.65fr repeat(3,1fr);min-height:147px;box-shadow:0 18px 40px #7c61400a}.overview>div{display:flex;align-items:center;justify-content:center;flex-direction:column;text-align:center;padding:18px 15px;position:relative}.overview>div+div:before{content:\"\";position:absolute;left:0;top:22%;bottom:22%;width:1px;background:var(--line)}.overview-lead{flex-direction:row!important;gap:15px;text-align:left!important}.overview-lead strong{font:500 69px/1 'Playfair Display',serif;color:#a76858}.overview-lead>span:last-child{max-width:150px;color:#6e5e55;font-size:13px;line-height:1.45}.overview-lead em{display:block;font:italic 17px 'Playfair Display',serif;color:#9f6d5f}.little-heart{font:32px 'Playfair Display',serif;color:var(--rose)}.overview-detail strong{font:500 34px/1.2 'Playfair Display',serif}.overview-detail span:last-child{color:#897b70;font-size:11px}.detail-icon{font-size:18px;color:var(--rose);height:25px}.main-grid{display:grid;grid-template-columns:1.16fr .84fr;gap:22px;margin-top:24px}.section-card{background:var(--paper);border:1px solid var(--line);padding:31px;min-width:0}.section-heading{display:flex;justify-content:space-between;gap:20px;align-items:start}.section-heading h2{font-size:30px}.ornament{font:31px 'Playfair Display',serif;color:#c5a99c;line-height:1}.guest-controls{display:flex;gap:12px;align-items:center;margin:27px 0 11px}.search{flex:1;display:flex;align-items:center;gap:8px;height:41px;padding:0 12px;background:#faf7f2;border:1px solid var(--line);color:#9a8072}.search span{font-size:23px;line-height:1}.search input{min-width:0;width:100%;border:0;background:transparent;outline:0;font-size:12px;color:var(--ink)}.filter-label{white-space:nowrap;font-size:11px;color:var(--muted)}.filter-label select{border:0;border-bottom:1px solid #cbb4a4;background:transparent;color:var(--ink);font-size:11px;font-weight:700;padding:4px;max-width:125px}.guest-list{max-height:405px;overflow:auto}.guest-row{display:grid;grid-template-columns:minmax(130px,1fr) auto;gap:12px;align-items:center;padding:15px 2px;border-bottom:1px solid #eee6dd}.guest-row:last-child{border:0}.guest-name{font-weight:700;font-size:13px}.guest-detail{display:block;color:#9a8a7e;font-size:11px;font-weight:400;margin-top:2px}.status{font-size:10px;font-weight:700;border-radius:99px;padding:5px 10px;background:#e7eee5;color:#5e765e;white-space:nowrap}.status.no{background:#f6e9e2;color:#9f6856}.status.pending{background:#f0ede8;color:#84786f}.message-list{display:grid;gap:14px;margin-top:25px;max-height:410px;overflow:auto}.message-card{background:#f8f3ed;padding:23px 23px 20px;border-left:2px solid #c39788}.message-card:before{content:'“';font:36px/20px 'Playfair Display',serif;color:#c39788}.message-card p{font:italic 17px/1.5 'Playfair Display',serif;margin:7px 0 13px;color:#5b493f}.message-card span{font-size:11px;font-weight:700;color:#9c7869}.message-count{font-size:11px;color:#9a8b7e;margin:15px 0 0}.empty{padding:34px 15px;color:#8d8076;text-align:center;font-size:12px;background:#faf7f2}.empty strong{display:block;font:500 20px 'Playfair Display',serif;color:#5a4a41;margin-bottom:5px}.planning{display:grid;grid-template-columns:1fr 1fr;gap:55px;align-items:center;margin-top:24px;padding:42px 47px;background:#ede7dc}.planning p:last-child{max-width:510px;line-height:1.75}.planning-summary>div{display:flex;justify-content:space-between;gap:20px;padding:13px 0;border-bottom:1px solid #d6c7b9;font-size:12px}.planning-summary>div:last-child{border:0}.planning-summary span{color:#776b61}.planning-summary strong{text-align:right;font-size:12px}footer{text-align:center;padding:27px;color:#897b70;font-size:11px;letter-spacing:.08em}footer span{padding:0 8px;color:var(--rose)}@media(max-width:950px){.site-header nav{gap:15px}.hero{grid-template-columns:50% 50%}.hero-copy{padding-left:45px;padding-right:35px}.overview{grid-template-columns:repeat(4,1fr)}.overview-lead{gap:7px}.overview-lead strong{font-size:55px}.little-heart{display:none}.main-grid{grid-template-columns:1fr 1fr}}@media(max-width:720px){.site-header{height:auto;min-height:70px;padding:15px 23px;flex-wrap:wrap}.site-header nav{order:3;width:100%;justify-content:space-between}.sync{font-size:10px}.hero{display:flex;flex-direction:column-reverse}.hero-photo{min-height:340px}.hero-copy{padding:40px 26px 30px}.hero h1{font-size:43px}.hero-note{padding-top:35px}.photo-caption{font-size:15px}.content{padding:0 18px 50px}.welcome{padding-top:47px;align-items:start}.overview{grid-template-columns:repeat(2,1fr)}.overview>div:nth-child(3):before{display:none}.overview-lead{grid-column:span 2;border-bottom:1px solid var(--line)}.overview>div:last-child{grid-column:span 2;border-top:1px solid var(--line)}.main-grid,.planning{grid-template-columns:1fr}.section-card{padding:23px}.planning{padding:30px 25px;gap:20px}}@media(max-width:440px){.brand-caption{font-size:9px}.sync{width:100%;order:2}.site-header nav{gap:8px;font-size:11px}.welcome{display:block}.welcome .refresh{margin-top:20px}.hero-photo{min-height:280px}.hero h1{font-size:39px}.overview-lead strong{font-size:60px}.guest-controls{flex-direction:column;align-items:stretch}.filter-label{align-self:flex-end}}@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}}\r\n</style>\r\n  <script src=\"/app.js\" defer></script>\r\n</head>\r\n<body>\r\n  <header class=\"site-header\">\r\n    <a class=\"brand\" href=\"#inicio\" aria-label=\"Ir al inicio\"><span class=\"brand-mark\">K<span>&</span>M</span><span class=\"brand-caption\">NUESTRO DÍA</span></a>\r\n    <nav aria-label=\"Secciones\"><a href=\"#invitados\">Invitados</a><a href=\"#mensajes\">Mensajes</a><a href=\"#organizacion\">Organización</a></nav>\r\n    <span class=\"sync\"><span class=\"sync-dot\"></span><span><span id=\"sync-text\">Cargando respuestas</span><small id=\"refresh-policy\" style=\"display:block;font-size:9px;color:#a39489;line-height:1.4\">Consulta automática cada minuto</small></span></span>\r\n  </header>\r\n\r\n  <main id=\"inicio\">\r\n    <section class=\"hero\" aria-labelledby=\"hero-title\">\r\n      <div class=\"hero-copy\">\r\n        <p class=\"eyebrow\">UN ESPACIO SOLO PARA USTEDES</p>\r\n        <h1 id=\"hero-title\">Su día se está llenando de <em>personas bonitas.</em></h1>\r\n        <p class=\"hero-intro\">Aquí pueden disfrutar cada confirmación, leer los buenos deseos y tener a mano lo esencial para celebrar juntos.</p>\r\n        <div class=\"hero-actions\"><a class=\"button button-primary\" href=\"#mensajes\">Leer sus mensajes <span aria-hidden=\"true\">↗</span></a><a class=\"text-link\" href=\"#invitados\">Ver quiénes vienen <span aria-hidden=\"true\">→</span></a></div>\r\n        <div class=\"hero-note\"><span class=\"note-line\"></span> KARINA <span class=\"note-heart\">♡</span> MICHAEL</div>\r\n      </div>\r\n      <div class=\"hero-photo\"><img src=\"data:image/jpeg;base64,\" alt=\"Karina y Michael tomados de las manos el día de su boda\"><div class=\"photo-caption\">Los mejores momentos se viven juntos.</div></div>\r\n    </section>\r\n\r\n    <div class=\"content\">\r\n      <div id=\"error\" class=\"error\" role=\"alert\" hidden></div>\r\n      <section class=\"welcome\" aria-labelledby=\"welcome-title\">\r\n        <div><p class=\"eyebrow\">CADA RESPUESTA ES UNA HISTORIA</p><h2 id=\"welcome-title\">Lo bonito de tenerlos cerca</h2><p>Un vistazo cálido a las personas que compartirán este momento con ustedes.</p></div>\r\n        <button type=\"button\" id=\"refresh\" class=\"refresh\">Actualizar respuestas <span aria-hidden=\"true\">↻</span></button>\r\n      </section>\r\n\r\n      <section class=\"overview\" aria-label=\"Resumen de confirmaciones\">\r\n        <div class=\"overview-lead\"><span class=\"little-heart\">♡</span><strong id=\"confirmed\">0</strong><span>personas han dicho <em>sí, allí estaremos</em></span></div>\r\n        <div class=\"overview-detail\"><span class=\"detail-icon\">✉</span><strong id=\"total\">0</strong><span>respuestas recibidas</span></div>\r\n        <div class=\"overview-detail\"><span class=\"detail-icon\">✧</span><strong id=\"ceremony\">0</strong><span>en la ceremonia</span></div>\r\n        <div class=\"overview-detail\"><span class=\"detail-icon\">♫</span><strong id=\"reception\">0</strong><span>en la recepción</span></div>\r\n      </section>\r\n\r\n      <div class=\"main-grid\">\r\n        <section class=\"section-card guests\" id=\"invitados\" aria-labelledby=\"guests-title\">\r\n          <div class=\"section-heading\"><div><p class=\"eyebrow\">QUIÉNES COMPARTIRÁN EL DÍA</p><h2 id=\"guests-title\">Nuestros invitados</h2><p id=\"guest-subtitle\">Las respuestas aparecerán aquí en cuanto lleguen.</p></div><span class=\"ornament\" aria-hidden=\"true\">✳</span></div>\r\n          <div class=\"guest-controls\"><label class=\"search\"><span aria-hidden=\"true\">⌕</span><input id=\"search\" type=\"search\" placeholder=\"Buscar un nombre\" aria-label=\"Buscar invitado por nombre\"></label><label class=\"filter-label\">Mostrar <select id=\"filter\" aria-label=\"Filtrar por asistencia\"><option value=\"all\">Todos</option><option value=\"yes\">Confirmados</option><option value=\"no\">No asistirán</option><option value=\"pending\">Por definir</option></select></label></div>\r\n          <div id=\"guest-list\" class=\"guest-list\" aria-live=\"polite\"></div>\r\n        </section>\r\n        <section class=\"section-card messages\" id=\"mensajes\" aria-labelledby=\"messages-title\"><div class=\"section-heading\"><div><p class=\"eyebrow\">PALABRAS PARA GUARDAR</p><h2 id=\"messages-title\">Mensajes con cariño</h2><p>Pequeños recuerdos que pueden volver a leer cuando quieran.</p></div><span class=\"ornament\" aria-hidden=\"true\">♡</span></div><div id=\"message-list\" class=\"message-list\" aria-live=\"polite\"></div><p id=\"message-count\" class=\"message-count\"></p></section>\r\n      </div>\r\n\r\n      <section class=\"planning\" id=\"organizacion\" aria-labelledby=\"planning-title\"><div><p class=\"eyebrow\">PARA ORGANIZAR CON CALMA</p><h2 id=\"planning-title\">Todo va tomando forma.</h2><p>Las respuestas del formulario les ayudan a preparar cada momento. Si necesitan un dato puntual, pueden encontrarlo en la lista de invitados.</p></div><div class=\"planning-summary\"><div><span>Confirmados para ceremonia</span><strong id=\"ceremony-summary\">0 personas</strong></div><div><span>Confirmados para recepción</span><strong id=\"reception-summary\">0 personas</strong></div><div><span>Última actualización</span><strong id=\"updated\">Pendiente</strong></div></div></section>\r\n    </div>\r\n  </main>\r\n  <footer>Karina & Michael <span>♡</span> Hecho con amor para recordar este día.</footer>\r\n<script>(() => {\r\n  const $ = id => document.getElementById(id);\r\n  const escapeHtml = value => String(value ?? '').replace(/[&<>\"']/g, char => ({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[char]));\r\n  const normalize = value => String(value ?? '').trim().toLowerCase().normalize('NFD').replace(/[\\u0300-\\u036f]/g, '');\r\n  const choice = value => {\r\n    const text = normalize(value);\r\n    if (/^(no|nop|no podre|no asistire|no voy|lamentablemente no)/.test(text)) return 'no';\r\n    if (/^(si|sip|claro|confirmo|asistire|asistimos|estare|estaremos|por supuesto|yes)/.test(text)) return 'yes';\r\n    return 'pending';\r\n  };\r\n  const plural = (count, singular, pluralForm) => `${count} ${count === 1 ? singular : pluralForm}`;\r\n  const dataUrl = window.RSVP_DATA_URL || '/api/respuestas';\r\n  if (window.RSVP_DATA_URL) $('refresh-policy').textContent = 'Consulta cada minuto · datos publicados aprox. cada 5 min';\r\n  let guests = [];\r\n\r\n  function parseCsv(input) {\r\n    const rows = []; let row = [], cell = '', quoted = false;\r\n    for (let i = 0; i < input.length; i++) {\r\n      const char = input[i];\r\n      if (char === '\"') { if (quoted && input[i + 1] === '\"') { cell += '\"'; i++; } else quoted = !quoted; }\r\n      else if (char === ',' && !quoted) { row.push(cell); cell = ''; }\r\n      else if ((char === '\\n' || char === '\\r') && !quoted) { if (char === '\\r' && input[i + 1] === '\\n') i++; row.push(cell); if (row.some(value => value.trim())) rows.push(row); row = []; cell = ''; }\r\n      else cell += char;\r\n    }\r\n    row.push(cell); if (row.some(value => value.trim())) rows.push(row);\r\n    if (rows[0]?.[0]) rows[0][0] = rows[0][0].replace(/^\\uFEFF/, '');\r\n    return rows;\r\n  }\r\n\r\n  function readRows(rows) {\r\n    const headers = (rows[0] || []).map(normalize);\r\n    const column = (name, fallback) => { const index = headers.findIndex(header => header.includes(name)); return index < 0 ? fallback : index; };\r\n    const fields = {name:column('nombre completo',1),status:column('confirma su asistencia',2),ceremony:column('ceremonia religiosa',3),reception:column('recepcion',4),message:column('buenos deseos',6)};\r\n    return rows.slice(1).filter(row => row.some(cell => String(cell ?? '').trim())).map(row => ({\r\n      name:String(row[fields.name] ?? '').trim() || 'Invitado sin nombre',\r\n      status:choice(row[fields.status]), ceremony:choice(row[fields.ceremony]), reception:choice(row[fields.reception]),\r\n      message:String(row[fields.message] ?? '').trim()\r\n    })).reverse();\r\n  }\r\n\r\n  function renderGuests() {\r\n    const query = normalize($('search').value), filter = $('filter').value;\r\n    const visible = guests.filter(guest => (filter === 'all' || guest.status === filter) && normalize(guest.name).includes(query));\r\n    $('guest-subtitle').textContent = guests.length ? plural(guests.length, 'respuesta recibida', 'respuestas recibidas') + ' para este día especial.' : 'Las respuestas aparecerán aquí en cuanto lleguen.';\r\n    $('guest-list').innerHTML = visible.length ? visible.map(guest => {\r\n      const moments = [guest.ceremony === 'yes' ? 'Ceremonia' : '', guest.reception === 'yes' ? 'Recepción' : ''].filter(Boolean).join(' · ');\r\n      const status = {yes:'¡Sí, estará!',no:'No podrá venir',pending:'Por definir'}[guest.status];\r\n      return `<article class=\"guest-row\"><div><span class=\"guest-name\">${escapeHtml(guest.name)}</span><span class=\"guest-detail\">${escapeHtml(moments || 'Sin momentos confirmados')}</span></div><span class=\"status ${guest.status}\">${status}</span></article>`;\r\n    }).join('') : `<div class=\"empty\"><strong>${guests.length ? 'No encontramos ese nombre' : 'Esperando las primeras respuestas'}</strong>${guests.length ? 'Prueba otra búsqueda o cambia el filtro.' : 'Cada confirmación tendrá aquí su lugar.'}</div>`;\r\n  }\r\n\r\n  function render() {\r\n    const confirmed = guests.filter(guest => guest.status === 'yes');\r\n    const ceremony = confirmed.filter(guest => guest.ceremony === 'yes').length;\r\n    const reception = confirmed.filter(guest => guest.reception === 'yes').length;\r\n    $('total').textContent = guests.length;\r\n    $('confirmed').textContent = confirmed.length;\r\n    $('ceremony').textContent = ceremony;\r\n    $('reception').textContent = reception;\r\n    $('ceremony-summary').textContent = plural(ceremony, 'persona', 'personas');\r\n    $('reception-summary').textContent = plural(reception, 'persona', 'personas');\r\n    const messages = guests.filter(guest => guest.message);\r\n    $('message-list').innerHTML = messages.length ? messages.slice(0, 8).map(guest => `<article class=\"message-card\"><p>${escapeHtml(guest.message)}</p><span>— ${escapeHtml(guest.name)}</span></article>`).join('') : '<div class=\"empty\"><strong>Pronto llegarán palabras bonitas</strong>Los mensajes que dejen sus invitados aparecerán aquí.</div>';\r\n    $('message-count').textContent = messages.length ? plural(messages.length, 'mensaje para ustedes', 'mensajes para ustedes') : '';\r\n    renderGuests();\r\n  }\r\n\r\n  async function load() {\r\n    const button = $('refresh');\r\n    button.disabled = true;\r\n    $('sync-text').textContent = 'Actualizando respuestas';\r\n    try {\r\n      const response = await fetch(dataUrl + '?ts=' + Date.now(), {cache:'no-store'});\r\n      if (!response.ok) throw new Error('El formulario no respondió correctamente.');\r\n      const data = window.RSVP_DATA_URL ? {rows:parseCsv(await response.text())} : await response.json();\r\n      if (!Array.isArray(data.rows)) throw new Error('Las respuestas no tienen el formato esperado.');\r\n      guests = readRows(data.rows);\r\n      render();\r\n      $('updated').textContent = new Date().toLocaleTimeString('es-PE', {hour:'2-digit',minute:'2-digit'});\r\n      $('sync-text').textContent = 'Respuestas actualizadas';\r\n      $('error').hidden = true;\r\n    } catch (error) {\r\n      $('sync-text').textContent = 'Sin conexión';\r\n      $('error').textContent = 'No se pudieron actualizar las respuestas. ' + error.message + ' Inténtalo de nuevo más tarde.';\r\n      $('error').hidden = false;\r\n      render();\r\n    } finally { button.disabled = false; }\r\n  }\r\n  $('search').addEventListener('input', renderGuests);\r\n  $('filter').addEventListener('change', renderGuests);\r\n  $('refresh').addEventListener('click', load);\r\n  render(); load(); setInterval(load, 60000);\r\n})();\r\n</script></body>\r\n</html>\r\n";
function parseCsv(input){const rows=[];let row=[],cell='',quoted=false;for(let i=0;i<input.length;i++){let c=input[i];if(c==='"'){if(quoted&&input[i+1]==='"'){cell+='"';i++}else quoted=!quoted}else if(c===','&&!quoted){row.push(cell);cell=''}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&input[i+1]==='\n')i++;row.push(cell);if(row.some(x=>x.trim()))rows.push(row);row=[];cell=''}else cell+=c}row.push(cell);if(row.some(x=>x.trim()))rows.push(row);if(rows[0]?.[0])rows[0][0]=rows[0][0].replace(/^\uFEFF/,'');return rows}
export default {async fetch(request){const path=new URL(request.url).pathname;if(path==='/api/respuestas'){try{const upstream=await fetch(csvUrl,{redirect:'follow',headers:{accept:'text/csv,text/plain;q=0.9,*/*;q=0.8'}});if(!upstream.ok)throw Error('La hoja no respondió correctamente');const rows=parseCsv(await upstream.text());if(!rows[0]?.some(x=>x.includes('Marca temporal')))throw Error('La hoja publicada no devolvió datos CSV');return Response.json({rows},{headers:{'cache-control':'no-store'}})}catch(e){return Response.json({error:e.message},{status:502,headers:{'cache-control':'no-store'}})}}if(path!=='/')return new Response('No encontrado',{status:404});return new Response(page,{headers:{'content-type':'text/html; charset=utf-8','cache-control':'no-cache'}})}};